struct SpinLock {
  std::atomic_flag f;  // C++20: clear
  void lock() {
    while (f.test_and_set(
             std::memory_order_acquire)) {}
  }
  void unlock() {
    f.clear(std::memory_order_release);
  }
};

bool locked = true;  // "held"
int data = 0;
void waiter() {
  while (locked) {}
  std::cout << "data=" << data;
}
int main() {
  std::thread t(waiter);
  std::this_thread::sleep_for(100ms);
  data = 42; locked = false;
  t.join();
}

std::atomic<bool> locked{true};
int data = 0;
void waiter() {
  while (locked.load(
           std::memory_order_acquire)) {}
  std::cout << "data=" << data;  // 42
}
// main:
data = 42;
locked.store(false,
             std::memory_order_release);
